import{_ as s,o as a,c as o,a as n}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"data/database/relational/mysql/interview.md","filePath":"data/database/relational/mysql/interview.md"}'),r={name:"data/database/relational/mysql/interview.md"};function d(e,t,i,l,h,g){return a(),o("div",null,[...t[0]||(t[0]=[n(`<p>对于Java面试中的MySQL部分，<strong>索引、事务与锁、日志与架构</strong>是三大核心板块，几乎覆盖了80%以上的考点。以下是按模块整理的高频面试题及详细解答。</p><hr><h2 id="一、基础架构篇" tabindex="-1">一、基础架构篇 <a class="header-anchor" href="#一、基础架构篇" aria-label="Permalink to &quot;一、基础架构篇&quot;">​</a></h2><h3 id="_1-mysql的基础架构分为哪几层-各层的核心职责是什么-mysql的默认引擎是什么" tabindex="-1">1. MySQL的基础架构分为哪几层？各层的核心职责是什么？MySQL的默认引擎是什么？ <a class="header-anchor" href="#_1-mysql的基础架构分为哪几层-各层的核心职责是什么-mysql的默认引擎是什么" aria-label="Permalink to &quot;1. MySQL的基础架构分为哪几层？各层的核心职责是什么？MySQL的默认引擎是什么？&quot;">​</a></h3><p>MySQL采用<strong>分层插件式架构</strong>，核心分为两大层：</p><ul><li><strong>Server层</strong>：MySQL的核心逻辑处理层，所有存储引擎共享。涵盖<strong>连接器、分析器、优化器、执行器</strong>四大组件，负责SQL解析、优化、执行、权限管控等逻辑计算。</li><li><strong>存储引擎层</strong>：数据持久化底座，插件式可插拔设计。负责数据的物理读写、持久化存储，提供事务、锁、MVCC、索引、崩溃恢复等底层能力。</li></ul><p>MySQL的默认引擎是InnoDB ，核心在于它完整支持 ACID 事务、行级锁（高并发友好）以及崩溃恢复能力（依靠 Redo Log），这些特性完美契合了现代互联网高并发、数据一致性的严苛要求。</p><h3 id="_2-一条sql语句的执行流程是怎样的" tabindex="-1">2. 一条SQL语句的执行流程是怎样的？ <a class="header-anchor" href="#_2-一条sql语句的执行流程是怎样的" aria-label="Permalink to &quot;2. 一条SQL语句的执行流程是怎样的？&quot;">​</a></h3><p>以<code>SELECT * FROM user WHERE id = 1</code>为例：</p><ol><li><strong>连接器</strong>：与客户端建立连接、身份认证、加载权限</li><li><strong>分析器</strong>：词法分析（识别关键字）→ 语法分析（检查SQL语法）</li><li><strong>优化器</strong>：决定使用哪个索引、Join顺序等（基于Cost成本模型）</li><li><strong>执行器</strong>：调用存储引擎接口获取数据</li></ol><blockquote><p>⚠️ <strong>避坑</strong>：MySQL 8.0已移除Query Cache，因为更新频繁的库命中率极低。</p></blockquote><h3 id="_3-为什么mysql连接建立后-管理员修改了用户权限-当前已建立的连接不生效" tabindex="-1">3. 为什么MySQL连接建立后，管理员修改了用户权限，当前已建立的连接不生效？ <a class="header-anchor" href="#_3-为什么mysql连接建立后-管理员修改了用户权限-当前已建立的连接不生效" aria-label="Permalink to &quot;3. 为什么MySQL连接建立后，管理员修改了用户权限，当前已建立的连接不生效？&quot;">​</a></h3><p>权限上下文在<strong>连接建立时一次性加载到内存</strong>中，后续操作均基于这份内存数据做校验，不会重新读取权限表。需<strong>断开重连</strong>才能加载新权限。</p><h3 id="_4-生产环境中mysql长连接出现内存溢出的原因是什么" tabindex="-1">4. 生产环境中MySQL长连接出现内存溢出的原因是什么？ <a class="header-anchor" href="#_4-生产环境中mysql长连接出现内存溢出的原因是什么" aria-label="Permalink to &quot;4. 生产环境中MySQL长连接出现内存溢出的原因是什么？&quot;">​</a></h3><p>MySQL执行SQL时使用的临时内存统一管理在连接对象中，<strong>只有连接断开才会释放</strong>。长期使用长连接执行大量大查询，会导致内存持续累积，最终OOM。</p><blockquote><p><strong>优化方案</strong>：MySQL 5.7+可使用<code>mysql_reset_connection</code>重置连接状态，无需重启服务。</p></blockquote><h2 id="二、存储引擎篇" tabindex="-1">二、存储引擎篇 <a class="header-anchor" href="#二、存储引擎篇" aria-label="Permalink to &quot;二、存储引擎篇&quot;">​</a></h2><h3 id="_1-innodb和myisam的核心区别是什么-⭐必考" tabindex="-1">1. InnoDB和MyISAM的核心区别是什么？（⭐必考） <a class="header-anchor" href="#_1-innodb和myisam的核心区别是什么-⭐必考" aria-label="Permalink to &quot;1. InnoDB和MyISAM的核心区别是什么？（⭐必考）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>InnoDB</th><th>MyISAM</th></tr></thead><tbody><tr><td>事务支持</td><td>支持ACID</td><td>不支持</td></tr><tr><td>锁粒度</td><td><strong>行级锁</strong>（高并发友好）</td><td><strong>表级锁</strong>（高并发阻塞）</td></tr><tr><td>崩溃恢复</td><td>支持（redo/undo日志）</td><td>不支持</td></tr><tr><td>聚簇索引</td><td>支持（数据与索引共存）</td><td>不支持（索引与数据分离）</td></tr><tr><td>外键</td><td>支持</td><td>不支持</td></tr><tr><td>全文索引</td><td>5.6+支持</td><td>原生支持</td></tr><tr><td>适用场景</td><td>写密集/高并发（订单、交易）</td><td>读密集（日志、静态数据）</td></tr></tbody></table><blockquote><p><strong>阿里视角</strong>：InnoDB支持行级锁和事务，适配高并发业务；MyISAM仅用于历史归档/只读场景。不要提&quot;MyISAM查询更快&quot;——通过索引/缓存优化，InnoDB读性能可持平MyISAM。</p></blockquote><p>面试回答重点：写锁阻塞机制 → 崩溃恢复代价 → 8.0版本趋势</p><p>在 MySQL 5.6 及之前，MyISAM 还能作为读多写少场景的备选；但从 MySQL 5.7 特别是 8.0 开始，InnoDB 已在全文索引、空间索引、原子 DDL 等方面全面补齐短板。现今的生产环境中，MyISAM 唯一合理的落脚点只有‘归档压缩表’和‘纯计数表’。但凡涉及任何一笔线上实时业务，选 InnoDB 是唯一正确的选择。</p><h2 id="三、索引篇-面试重灾区-80-性能问题在此" tabindex="-1">三、索引篇（面试重灾区，80%性能问题在此） <a class="header-anchor" href="#三、索引篇-面试重灾区-80-性能问题在此" aria-label="Permalink to &quot;三、索引篇（面试重灾区，80%性能问题在此）&quot;">​</a></h2><h3 id="_1-为什么mysql选择b-树作为索引结构-⭐必考-经典三连问" tabindex="-1">1. 为什么MySQL选择B+树作为索引结构？（⭐必考，经典三连问） <a class="header-anchor" href="#_1-为什么mysql选择b-树作为索引结构-⭐必考-经典三连问" aria-label="Permalink to &quot;1. 为什么MySQL选择B+树作为索引结构？（⭐必考，经典三连问）&quot;">​</a></h3><blockquote><p><strong>数据库索引优化的本质，是最小化磁盘I/O次数。</strong> 一次磁盘I/O（约10ms）≈ 10万次内存操作（纳秒级）。所有索引结构的PK，都是围绕“如何降低磁盘I/O”展开。</p></blockquote><h4 id="一、为什么不选其他结构" tabindex="-1">一、为什么不选其他结构？ <a class="header-anchor" href="#一、为什么不选其他结构" aria-label="Permalink to &quot;一、为什么不选其他结构？&quot;">​</a></h4><table tabindex="0"><thead><tr><th>数据结构</th><th>淘汰原因</th></tr></thead><tbody><tr><td><strong>Hash</strong></td><td>Hash是O(1)最快，但是 ①不支持范围查询和排序；②Hash冲突时多次随机I/O，无法利用磁盘顺序预读</td></tr><tr><td><strong>二叉树/红黑树</strong></td><td>1000万数据树高≈24层，查一条需<strong>24次磁盘I/O</strong>（24×10ms=240ms），高并发下磁盘直接卡死——<strong>树太高是硬伤</strong></td></tr><tr><td><strong>B树</strong></td><td>非叶子节点同时存Key+Data，16KB页假设每行1KB只能存16条，存储千万数据时树高飙升，需要<strong>5~6次I/O</strong></td></tr></tbody></table><h4 id="二、b-树凭什么封神-核心计算" tabindex="-1">二、B+树凭什么封神？（核心计算） <a class="header-anchor" href="#二、b-树凭什么封神-核心计算" aria-label="Permalink to &quot;二、B+树凭什么封神？（核心计算）&quot;">​</a></h4><ol><li>多路平衡树：非叶子节点存储<strong>key+指针</strong>，叶子节点存储完整行数据。相同磁盘页可存更多键值→<strong>树高更低</strong>（通常3~4层，10亿数据仅需4次IO）</li><li>有序性：叶子节点形成<strong>有序双向链表</strong>→范围查询和排序效率极高</li><li>高度平衡：所有叶子节点位于同一层，查询稳定O(log n)</li><li>磁盘IO优化：一次IO可加载更多索引，大幅减少磁盘访问次数</li></ol><p>拓展知识：</p><ul><li>InnoDB一页是16KB，16KB数据页，Key（BIGINT 8字节）+ 指针（6字节）= 14字节/条</li><li>单页可存索引数 = <code>16KB / 14B ≈ 1170个</code></li></ul><p><strong>树高推导（面试丢出这组数字直接满分）</strong>：</p><table tabindex="0"><thead><tr><th>层数</th><th>可容纳数据量</th></tr></thead><tbody><tr><td>第1层（根节点）</td><td>1170 个指针</td></tr><tr><td>第2层</td><td>1170 × 1170 = <strong>136万</strong></td></tr><tr><td>第3层</td><td>1170 × 1170 × 1170 ≈ <strong>13.7亿</strong></td></tr></tbody></table><blockquote><p><strong>结论</strong>：13.7亿条数据，B+树高度仅<strong>3~4层</strong>，查一条最多3~4次磁盘I/O（根节点常驻内存，实际仅2~3次物理I/O）。</p></blockquote><h4 id="三、b-树的额外优势-拉开差距的加分点" tabindex="-1">三、B+树的额外优势（拉开差距的加分点） <a class="header-anchor" href="#三、b-树的额外优势-拉开差距的加分点" aria-label="Permalink to &quot;三、B+树的额外优势（拉开差距的加分点）&quot;">​</a></h4><ol><li><strong>范围查询</strong>：叶子节点形成<strong>有序双向链表</strong>，范围查询只需沿链表走，且触发磁盘<strong>顺序预读</strong>（一次I/O读入连续多页），B树则需要回溯中序遍历，产生大量随机I/O。</li><li><strong>聚簇索引亲和</strong>：叶子节点存完整行数据，主键自增插入时数据页顺序追加，<strong>无页分裂开销</strong>（这也是阿里规范要求主键自增的底层原因）。</li></ol><h4 id="四、进阶追问-跨界碾压" tabindex="-1">四、进阶追问（跨界碾压） <a class="header-anchor" href="#四、进阶追问-跨界碾压" aria-label="Permalink to &quot;四、进阶追问（跨界碾压）&quot;">​</a></h4><p>面试官挖坑——“MongoDB用B树，Redis用跳表，为什么MySQL非要用B+树？</p><p>MySQL是<strong>磁盘数据库</strong>，B+树专门针对磁盘块预读（Page Cache）优化，将随机I/O转化为顺序I/O。Redis基于内存，寻址成本≈0，跳表实现简单且并发友好；MongoDB非关系型，B树在文档随机访问上有优势。<strong>场景不同，架构选型不同</strong>。</p><h4 id="面试完整话术-直接背" tabindex="-1">面试完整话术（直接背） <a class="header-anchor" href="#面试完整话术-直接背" aria-label="Permalink to &quot;面试完整话术（直接背）&quot;">​</a></h4><ul><li>B+树的核心竞争力在于<strong>磁盘I/O成本的极致压缩</strong></li><li>Hash不支持范围，红黑树1000万数据要24次I/O，B树因为非叶子节点存Data导致单页存不了几个Key，三者各有硬伤。</li><li>B+树做了极致优化——<strong>非叶子节点只存键值</strong>，单页可存上千个索引，对于千万级数据，树高牢牢控制在 <strong>3层以内</strong>。同时，叶子节点的<strong>有序双向链表</strong>让范围查询和排序能利用磁盘‘顺序预读’，性能吊打B树。因此，无论从I/O次数还是存储空间利用率上，B+树都是关系型磁盘数据库的终极选择。</li></ul><hr><h3 id="_2-什么是聚簇索引-什么是非聚簇索引-核心区别是什么-⭐必考" tabindex="-1">2. 什么是聚簇索引？什么是非聚簇索引？核心区别是什么？（⭐必考） <a class="header-anchor" href="#_2-什么是聚簇索引-什么是非聚簇索引-核心区别是什么-⭐必考" aria-label="Permalink to &quot;2. 什么是聚簇索引？什么是非聚簇索引？核心区别是什么？（⭐必考）&quot;">​</a></h3><ul><li>聚簇索引：包含完整数据行，指主键，一张表只能有一个。</li><li>二级索引：包含索引列和主键值/指针，允许多个。</li><li>联合索引：多个列组合，需要遵循最左匹配原则。</li><li>覆盖索引：包含查询所有字段的索引，避免回表。</li></ul><p>本质区别：聚簇索引将索引和数据<strong>绑定在同一棵B+树上</strong>，查主键直接命中数据行，<strong>一次I/O</strong>搞定。</p><blockquote><p><strong>InnoDB实现规则</strong>：</p><ul><li>有主键 → 主键作为聚簇索引</li><li>无主键 → 第一个唯一非空索引作为聚簇索引</li><li>都没有 → 隐式创建6字节ROWID</li></ul></blockquote><hr><h3 id="_3-为什什么聚簇索引的插入速度慢" tabindex="-1">3. 为什什么聚簇索引的插入速度慢？ <a class="header-anchor" href="#_3-为什什么聚簇索引的插入速度慢" aria-label="Permalink to &quot;3. 为什什么聚簇索引的插入速度慢？&quot;">​</a></h3><p>页分裂发生的根本原因：B+树叶子节点按主键顺序存储。如果主键不规律（如UUID、业务字符串），插入位置可能在<strong>已满的数据页中间</strong>。</p><p>此时InnoDB必须：</p><ol><li>分配新数据页</li><li>将原页约50%的数据迁移到新页</li><li>调整父节点的指针</li></ol><p>这涉及<strong>大量的随机I/O和磁盘碎片</strong>。而<strong>自增主键</strong>每次都追加在最后，仅需在最后一页写入——所以阿里规范要求<strong>主键必须自增，且无业务含义</strong>。</p><hr><h3 id="_4-一个表能不能有多个聚簇索引" tabindex="-1">4. 一个表能不能有多个聚簇索引？ <a class="header-anchor" href="#_4-一个表能不能有多个聚簇索引" aria-label="Permalink to &quot;4. 一个表能不能有多个聚簇索引？&quot;">​</a></h3><p><strong>绝对不能。</strong> 聚簇索引决定了<strong>数据的物理存储顺序</strong>，一行数据在磁盘上只有一个物理位置，所以只能有一种排序方式。这就好比书架上的书只能按一种规则（如拼音）排列，不可能同时按拼音和笔画排。</p><hr><h3 id="_5-为什么《阿里java开发手册》规定-主键必须自增且无业务含义" tabindex="-1">5. 为什么《阿里Java开发手册》规定“主键必须自增且无业务含义”？ <a class="header-anchor" href="#_5-为什么《阿里java开发手册》规定-主键必须自增且无业务含义" aria-label="Permalink to &quot;5. 为什么《阿里Java开发手册》规定“主键必须自增且无业务含义”？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>原因</th><th>说明</th></tr></thead><tbody><tr><td><strong>避免页分裂</strong></td><td>自增主键顺序写入，数据页永不分裂，写入性能最优</td></tr><tr><td><strong>降低二级索引存储开销</strong></td><td>二级索引叶子节点存储主键值，主键越短（BIGINT 8字节），二级索引越瘦小，节省磁盘I/O</td></tr><tr><td><strong>业务解耦</strong></td><td>主键一旦带有业务含义（如身份证号），未来业务变更（如身份证升位）会导致大规模索引重构</td></tr></tbody></table><hr><h3 id="_6-innodb的二级索引-非聚簇索引-和myisam的索引有什么区别-⭐阿里必问" tabindex="-1">6. InnoDB的二级索引（非聚簇索引）和MyISAM的索引有什么区别？（⭐阿里必问） <a class="header-anchor" href="#_6-innodb的二级索引-非聚簇索引-和myisam的索引有什么区别-⭐阿里必问" aria-label="Permalink to &quot;6. InnoDB的二级索引（非聚簇索引）和MyISAM的索引有什么区别？（⭐阿里必问）&quot;">​</a></h3><p>这是面试官用来区分你是“背表格”还是“真懂”的关键问题：</p><table tabindex="0"><thead><tr><th>对比维度</th><th>InnoDB的二级索引</th><th>MyISAM的索引</th></tr></thead><tbody><tr><td>叶子节点内容</td><td><strong>主键值</strong>（不是物理地址）</td><td><strong>数据行的物理地址</strong>（行偏移量）</td></tr><tr><td>数据移动影响</td><td>数据行移动时，二级索引<strong>无需更新</strong>（主键不变）</td><td>数据行移动时，所有索引都要<strong>更新地址</strong></td></tr><tr><td>回表方式</td><td>先查二级索引拿主键 → 再去聚簇索引查行</td><td>先查索引拿物理地址 → 直接去数据文件读行</td></tr></tbody></table><blockquote><p><strong>关键洞察</strong>：InnoDB用主键做“中间层”隔开索引和物理地址，只要主键不变，数据行在磁盘上的移动不会影响二级索引的有效性。而MyISAM的索引直接指向物理地址，数据行移动（如<code>UPDATE</code>变长字段）时要同步更新所有索引——维护成本极高。</p></blockquote><hr><h3 id="_7-什么情况下非聚簇索引比聚簇索引更快-反直觉考点" tabindex="-1">7. 什么情况下非聚簇索引比聚簇索引更快？（反直觉考点） <a class="header-anchor" href="#_7-什么情况下非聚簇索引比聚簇索引更快-反直觉考点" aria-label="Permalink to &quot;7. 什么情况下非聚簇索引比聚簇索引更快？（反直觉考点）&quot;">​</a></h3><p><strong>覆盖索引</strong>。</p><p>如果二级索引已经包含了查询所需的所有字段（<code>SELECT name, age FROM user WHERE name = &#39;张三&#39;</code>，索引为<code>(name, age)</code>），则<strong>直接读二级索引就拿到数据，完全不需要回表</strong>。此时二级索引的B+树比聚簇索引更“矮胖”（叶子节点不存完整行数据，单页可存更多索引项），遍历速度反而更快。</p><hr><h3 id="_8-什么是回表操作-如何避免-⭐必考" tabindex="-1">8. 什么是回表操作？如何避免？（⭐必考） <a class="header-anchor" href="#_8-什么是回表操作-如何避免-⭐必考" aria-label="Permalink to &quot;8. 什么是回表操作？如何避免？（⭐必考）&quot;">​</a></h3><p><strong>回表</strong>：命中二级索引找到主键值后，需要重新根据主键值到聚簇索引中查找完整数据行的过程，有多少条数据就要回多少次表。</p><p><strong>原因</strong>：InnoDB的二级索引叶子节点只存储主键值，不存储完整数据行。</p><p><strong>避免方法——覆盖索引</strong>：建联合索引包含查询所需的所有字段，使查询<strong>无需回表</strong>。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 建联合索引 (name, email)</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> name</span><span class="__shiki_140thh">, email </span><span class="__shiki_1itgoe">FROM</span><span class="__shiki_140thh"> users </span><span class="__shiki_1itgoe">WHERE</span><span class="__shiki_1itgoe"> name</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_mdbnqw"> &#39;张三&#39;</span><span class="__shiki_140thh">;</span></span>
<span class="line"><span class="__shiki_21nrsd">-- 因为联合索引 (name, email) 包含了查询所需的所有字段（name和email），</span></span>
<span class="line"><span class="__shiki_21nrsd">-- 所以这个索引在此查询中成为了一个【覆盖索引】，无需回表！</span></span></code></pre></div><hr><h3 id="_9-什么情况下索引会失效-⭐必考-高频翻车场景" tabindex="-1">9. 什么情况下索引会失效？（⭐必考，高频翻车场景） <a class="header-anchor" href="#_9-什么情况下索引会失效-⭐必考-高频翻车场景" aria-label="Permalink to &quot;9. 什么情况下索引会失效？（⭐必考，高频翻车场景）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>是否走索引</th><th>示例</th></tr></thead><tbody><tr><td>对字段使用函数</td><td>❌</td><td><code>WHERE YEAR(create_time) = 2024</code></td></tr><tr><td>左模糊查询</td><td>❌</td><td><code>WHERE name LIKE &#39;%张&#39;</code></td></tr><tr><td>索引列做加减乘除</td><td>❌</td><td>WHERE id + 1 = 10（需改为 WHERE id = 9）</td></tr><tr><td>隐式类型转换</td><td>❌</td><td><code>WHERE user_id = &#39;123&#39;</code>（user_id是INT）</td></tr><tr><td>OR条件部分无索引</td><td>❌</td><td><code>WHERE name=&#39;A&#39; OR age=20</code>（age无索引）</td></tr><tr><td>不符合最左前缀</td><td>❌</td><td>联合索引(a,b,c)，查<code>WHERE b=1 AND c=2</code></td></tr><tr><td>!= / NOT IN</td><td>❌</td><td><code>WHERE id != 1</code></td></tr><tr><td>WHERE name IS NULL</td><td>✅</td><td>通常走索引 NULL值在B+树中集中存放在最左侧（或最右侧），可直接定位</td></tr><tr><td>WHERE name IS NOT NULL</td><td>❌</td><td>通常不走索引 匹配范围太大，优化器认为回表成本高于全表扫描</td></tr></tbody></table><blockquote><p><strong>注意</strong>：有时索引没生效，是优化器觉得<strong>全表扫描比走索引回表更划算</strong>（基于Cost成本模型）。</p></blockquote><p>进阶场景：</p><ol><li><code>ORDER BY</code> / <code>GROUP BY</code> 排序方向不一致</li></ol><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 联合索引 (a, b)</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> *</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_140thh"> t </span><span class="__shiki_1itgoe">ORDER BY</span><span class="__shiki_140thh"> a </span><span class="__shiki_1itgoe">ASC</span><span class="__shiki_140thh">, b </span><span class="__shiki_1itgoe">DESC</span><span class="__shiki_140thh">;  </span><span class="__shiki_21nrsd">-- ❌ 索引失效（排序方向相反）</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> *</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_140thh"> t </span><span class="__shiki_1itgoe">ORDER BY</span><span class="__shiki_140thh"> a </span><span class="__shiki_1itgoe">ASC</span><span class="__shiki_140thh">, b </span><span class="__shiki_1itgoe">ASC</span><span class="__shiki_140thh">;   </span><span class="__shiki_21nrsd">-- ✅ 走索引</span></span></code></pre></div><blockquote><p>底层原因：B+树的排序方向是固定的，ASC走正向链表，DESC走反向链表，混合排序无法在同一个索引树方向上完成，必须触发Using filesort。</p></blockquote><ol start="2"><li>跨表连接时“字符集/排序规则”不一致</li></ol><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- t1表的 name 是 utf8mb4_general_ci，t2表的 name 是 utf8mb4_unicode_ci</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> *</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_140thh"> t1 </span><span class="__shiki_1itgoe">JOIN</span><span class="__shiki_140thh"> t2 </span><span class="__shiki_1itgoe">ON</span><span class="__shiki_dzsirb"> t1</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">name</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_dzsirb"> t2</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">name</span><span class="__shiki_140thh">;  </span><span class="__shiki_21nrsd">-- ❌ 关联字段索引失效</span></span></code></pre></div><blockquote><p>底层原因：排序规则不同，MySQL无法直接比较二进制值，必须隐式转换，使索引列失效。这是生产环境中最容易被忽视的索引失效场景。</p></blockquote><hr><h3 id="_10-联合索引的最左前缀原则是什么" tabindex="-1">10. 联合索引的最左前缀原则是什么？ <a class="header-anchor" href="#_10-联合索引的最左前缀原则是什么" aria-label="Permalink to &quot;10. 联合索引的最左前缀原则是什么？&quot;">​</a></h3><p>联合索引<code>(a, b, c)</code>遵循<strong>最左前缀原则</strong>——查询条件必须从索引的最左列开始，且<strong>不能跳过中间的列</strong>。</p><h4 id="法则1-范围查询后-索引列-全军覆没" tabindex="-1">法则1：范围查询后，索引列“全军覆没” <a class="header-anchor" href="#法则1-范围查询后-索引列-全军覆没" aria-label="Permalink to &quot;法则1：范围查询后，索引列“全军覆没”&quot;">​</a></h4><ul><li>✅ <code>WHERE a = 1 AND b = 2</code> → 走索引</li><li>✅ <code>WHERE a = 1</code> → 走索引</li><li>❌ <code>WHERE b = 2 AND c = 3</code> → <strong>不走索引</strong>（跳过了a）</li><li>⚠️ <code>WHERE a = 1 AND c = 3</code> → 只用到a，c不走索引（跳过了b）</li></ul><blockquote><p><strong>底层原因</strong>：B+树中，当 <code>b &gt; 10</code> 时，命中的数据行在物理上是不连续的，索引无法再按 <code>c</code> 排序，所以 <code>c</code> 只能回表过滤。 <strong>优化技巧</strong>：在设计联合索引时，<strong>等值查询放最前，范围查询（<code>&gt;</code>、<code>&lt;</code>、<code>BETWEEN</code>、<code>LIKE</code>）放最后</strong>，这是建索引的第一原则。。</p></blockquote><h4 id="法则2-order-by-和-where-共享最左前缀但规则不同" tabindex="-1">法则2：<code>ORDER BY</code> 和 <code>WHERE</code> 共享最左前缀但规则不同 <a class="header-anchor" href="#法则2-order-by-和-where-共享最左前缀但规则不同" aria-label="Permalink to &quot;法则2：\`ORDER BY\` 和 \`WHERE\` 共享最左前缀但规则不同&quot;">​</a></h4><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 联合索引 (a, b, c)</span></span>
<span class="line"><span class="__shiki_1itgoe">WHERE</span><span class="__shiki_140thh"> a </span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb"> 1</span><span class="__shiki_1itgoe"> ORDER BY</span><span class="__shiki_140thh"> b;   </span><span class="__shiki_21nrsd">-- ✅ 走索引（a 常量过滤后，b 在结果集中有序）</span></span>
<span class="line"><span class="__shiki_1itgoe">WHERE</span><span class="__shiki_140thh"> b </span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb"> 1</span><span class="__shiki_1itgoe"> ORDER BY</span><span class="__shiki_140thh"> a;   </span><span class="__shiki_21nrsd">-- ❌ 无法走索引，触发 filesort</span></span>
<span class="line"><span class="__shiki_1itgoe">ORDER BY</span><span class="__shiki_140thh"> a, b;            </span><span class="__shiki_21nrsd">-- ✅ 走索引</span></span>
<span class="line"><span class="__shiki_1itgoe">ORDER BY</span><span class="__shiki_140thh"> b, a;            </span><span class="__shiki_21nrsd">-- ❌ 不走索引（顺序不一致）</span></span></code></pre></div><blockquote><p><strong>关键认知</strong>：<code>ORDER BY</code> 要利用索引，前提是 <strong><code>WHERE</code> 中的等值条件先消耗掉索引左侧列</strong>，剩余列的排序顺序必须与索引定义完全一致。</p></blockquote><h4 id="法则3-mysql-8-0-的-跳跃扫描-skip-scan-——-颠覆认知的加分点" tabindex="-1">法则3：MySQL 8.0 的“跳跃扫描”（Skip Scan）—— 颠覆认知的加分点 <a class="header-anchor" href="#法则3-mysql-8-0-的-跳跃扫描-skip-scan-——-颠覆认知的加分点" aria-label="Permalink to &quot;法则3：MySQL 8.0 的“跳跃扫描”（Skip Scan）—— 颠覆认知的加分点&quot;">​</a></h4><p><strong>传统认知</strong>：<code>WHERE b = 1</code>（跳过 <code>a</code>）→ 绝对不走索引 <code>(a,b)</code>。</p><p><strong>MySQL 8.0 新特性</strong>：在满足 <strong><code>a</code> 的基数极低（如性别：男/女）</strong> 且优化器认为值得时，MySQL 8.0 会执行 <strong>跳跃扫描（Skip Scan）</strong>——自动将 <code>WHERE b = 1</code> 拆解为： <code>WHERE a = &#39;男&#39; AND b = 1 UNION ALL WHERE a = &#39;女&#39; AND b = 1</code>，从而实现<strong>走索引</strong>。</p><blockquote><p><strong>面试话术</strong>：“在 MySQL 8.0 之前，跳过最左列绝对走不了索引。但 8.0 引入了 Skip Scan，当被跳过的列区分度极低时，优化器会自动改写查询，利用索引。但这只是 8.0 的特例，不能作为通用优化手段。”</p></blockquote><p><strong>EXPLAIN 验证</strong>：<code>Extra</code> 字段显示 <code>Using index for skip scan</code> 即触发此机制。</p><h3 id="_11-面试完整话术-直接背" tabindex="-1">11. 面试完整话术（直接背） <a class="header-anchor" href="#_11-面试完整话术-直接背" aria-label="Permalink to &quot;11. 面试完整话术（直接背）&quot;">​</a></h3><ul><li>聚簇索引是<strong>数据即索引、索引即数据</strong>，叶子节点存完整行，查主键只需一次I/O。一个表只能有一个，因为它决定了数据的物理排列顺序。</li><li>非聚簇索引（二级索引）叶子节点存的是<strong>主键值</strong>，查询需要先查二级索引拿主键、再回聚簇索引查行——这是‘回表’的由来。</li><li>InnoDB用主键作为中间层，隔离了索引与物理地址的耦合，数据移动时二级索引无需更新，维护成本远低于MyISAM的直接地址索引。这也是为什么选主键要选<strong>自增且短小的业务无关列</strong>——既避免页分裂，又让二级索引更轻量。</li><li>索引失效：“除了常规的函数运算和左模糊，我特别关注两个隐藏痛点：一是<strong>索引列做算术运算</strong>，比如 <code>WHERE id + 1 = 10</code>，这在代码 Review 中极难发现；二是<strong>表关联时的字符集不一致</strong>，会触发隐式转换导致索引失效，线上大表 Join 瞬间打挂数据库。”</li><li>最左前缀：“最左前缀的核心是<strong>索引列的有序性</strong>。等值查询消耗掉左侧列后，剩余列依然有序；但范围查询会<strong>截断有序性</strong>，所以范围条件必须放最后。如果是 <code>ORDER BY</code>，还需要注意排序方向必须一致。不过 MySQL 8.0 的跳跃扫描是个例外，在低基数列上能绕过最左前缀限制。”</li></ul><h2 id="四、事务篇" tabindex="-1">四、事务篇 <a class="header-anchor" href="#四、事务篇" aria-label="Permalink to &quot;四、事务篇&quot;">​</a></h2><h3 id="_1-事务的acid特性是什么" tabindex="-1">1. 事务的ACID特性是什么？ <a class="header-anchor" href="#_1-事务的acid特性是什么" aria-label="Permalink to &quot;1. 事务的ACID特性是什么？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>含义</th><th>实现技术</th></tr></thead><tbody><tr><td><strong>Atomicity（原子性）</strong></td><td>事务要么全部成功，要么全部失败</td><td><strong>Undo Log</strong>（回滚日志）</td></tr><tr><td><strong>Consistency（一致性）</strong></td><td>事务前后数据保持逻辑一致</td><td>原子性+隔离性+持久性共同保证</td></tr><tr><td><strong>Isolation（隔离性）</strong></td><td>事务之间互不干扰</td><td><strong>MVCC + 锁机制</strong></td></tr><tr><td><strong>Durability（持久性）</strong></td><td>事务提交后数据永久保存</td><td><strong>Redo Log</strong>（重做日志）</td></tr></tbody></table><blockquote><p><strong>核心认知</strong>：<strong>一致性是目标</strong>，原子性、隔离性、持久性是<strong>手段</strong>。AID是数据库的机制，C是业务层面的结果。</p></blockquote><hr><h3 id="_2-atomicity-原子性-——undo-log具体怎么实现回滚" tabindex="-1">2. Atomicity（原子性）——Undo Log具体怎么实现回滚？ <a class="header-anchor" href="#_2-atomicity-原子性-——undo-log具体怎么实现回滚" aria-label="Permalink to &quot;2. Atomicity（原子性）——Undo Log具体怎么实现回滚？&quot;">​</a></h3><p><strong>关键点</strong>：Undo Log记录的是<strong>数据修改前的旧值</strong>（逻辑日志）。</p><ul><li><strong>INSERT</strong> → Undo Log记录<strong>主键ID</strong>（回滚时执行 <code>DELETE</code>）</li><li><strong>DELETE</strong> → Undo Log记录<strong>完整行数据</strong>（回滚时执行 <code>INSERT</code>）</li><li><strong>UPDATE</strong> → Undo Log记录<strong>修改前的行数据</strong>（回滚时执行反向 <code>UPDATE</code>）</li></ul><p><strong>回滚流程</strong>：事务执行中发生异常或执行 <code>ROLLBACK</code>，InnoDB根据Undo Log<strong>逆向操作</strong>，将数据恢复为修改前的状态。</p><p><strong>额外作用</strong>：Undo Log不只是回滚，它还服务于<strong>MVCC</strong>——当Read View需要读取某个版本的数据时，通过Undo Log版本链回溯到可见版本。</p><hr><h3 id="_3-durability-持久性-——redo-log为什么比直接写数据文件快-⭐必考" tabindex="-1">3. Durability（持久性）——Redo Log为什么比直接写数据文件快？（⭐必考） <a class="header-anchor" href="#_3-durability-持久性-——redo-log为什么比直接写数据文件快-⭐必考" aria-label="Permalink to &quot;3. Durability（持久性）——Redo Log为什么比直接写数据文件快？（⭐必考）&quot;">​</a></h3><p><strong>核心原理：顺序写 vs 随机写</strong></p><table tabindex="0"><thead><tr><th>对比</th><th>Redo Log</th><th>数据文件</th></tr></thead><tbody><tr><td>写入方式</td><td><strong>顺序追加写</strong>（Append-only）</td><td><strong>随机写</strong>（数据页分散在各处）</td></tr><tr><td>写入时机</td><td>事务提交时<strong>立即写</strong></td><td>异步刷盘（Checkpoint）</td></tr><tr><td>I/O类型</td><td>顺序I/O，极快</td><td>随机I/O，极慢</td></tr></tbody></table><p><strong>WAL技术（Write-Ahead Logging）</strong> ：<strong>先写日志，再写磁盘</strong>。事务提交时，只需把Redo Log刷入磁盘（顺序写），就认为事务已持久化，数据页可以稍后异步刷盘。这样既保证了持久性，又极大提升了写入性能。 <strong>崩溃恢复</strong>：MySQL宕机重启时，通过Redo Log重放已提交但未刷盘的事务，确保数据不丢失。</p><h3 id="_4-isolation-隔离性-——mvcc和锁的分工是什么" tabindex="-1">4. Isolation（隔离性）——MVCC和锁的分工是什么？ <a class="header-anchor" href="#_4-isolation-隔离性-——mvcc和锁的分工是什么" aria-label="Permalink to &quot;4. Isolation（隔离性）——MVCC和锁的分工是什么？&quot;">​</a></h3><p><strong>关键认知</strong>：隔离性由<strong>MVCC + 锁</strong>共同实现，但各司其职：</p><ul><li><strong>MVCC（多版本并发控制）</strong> ：解决<strong>读写冲突</strong>（读不加锁，写不阻塞读）。读操作通过Read View和Undo Log版本链读取快照数据，无需加锁。</li><li><strong>锁机制</strong>：解决<strong>写写冲突</strong>（两个事务同时修改同一行）。行锁保证同一行数据同时只能被一个事务修改。</li></ul><table tabindex="0"><thead><tr><th>场景</th><th>解决方案</th></tr></thead><tbody><tr><td>读写并发</td><td><strong>MVCC</strong>（读快照，不加锁）</td></tr><tr><td>写写并发</td><td><strong>行锁</strong>（排他锁互斥）</td></tr><tr><td>防止幻读（RR级别）</td><td><strong>间隙锁（Gap Lock）</strong> + MVCC</td></tr></tbody></table><hr><h3 id="_5-consistency-一致性-——为什么说-c是结果-不是手段" tabindex="-1">5. Consistency（一致性）——为什么说“C是结果，不是手段”？ <a class="header-anchor" href="#_5-consistency-一致性-——为什么说-c是结果-不是手段" aria-label="Permalink to &quot;5. Consistency（一致性）——为什么说“C是结果，不是手段”？&quot;">​</a></h3><p><strong>回答</strong>：一致性是<strong>事务的最终目标</strong>，而不是某个组件直接实现的。它由AID三者共同保障：</p><ul><li><strong>原子性</strong>保证事务不会半途而废 → 数据不会处于中间状态</li><li><strong>隔离性</strong>保证并发事务不互相干扰 → 数据不会被交叉污染</li><li><strong>持久性</strong>保证提交数据不丢失 → 数据最终可靠落地</li></ul><p><strong>但更重要的是</strong>：一致性还需要<strong>应用层配合</strong>——比如转账业务，A转给B 100元，代码逻辑必须是 <code>A余额-100</code> 和 <code>B余额+100</code> 同时执行。如果业务代码本身写错了（只减不增），AID再强也保证不了一致性。</p><blockquote><p><strong>面试必杀句</strong>：“一致性是数据库和应用程序<strong>共同承担</strong>的责任。数据库保证数据不坏，应用程序保证业务不错。”</p></blockquote><hr><h3 id="_6-redo-log和undo-log能互相替代吗-区分是否真懂的关键" tabindex="-1">6. Redo Log和Undo Log能互相替代吗？（区分是否真懂的关键） <a class="header-anchor" href="#_6-redo-log和undo-log能互相替代吗-区分是否真懂的关键" aria-label="Permalink to &quot;6. Redo Log和Undo Log能互相替代吗？（区分是否真懂的关键）&quot;">​</a></h3><p><strong>绝对不能。</strong></p><ul><li><strong>Redo Log</strong> 解决的是<strong>持久化</strong>问题（崩溃恢复）。它记录的是数据页的物理变化（“做了什么”），是<strong>物理日志</strong>。</li><li><strong>Undo Log</strong> 解决的是<strong>原子性</strong>问题（事务回滚）。它记录的是修改前的逻辑状态（“怎么改回来”），是<strong>逻辑日志</strong>。</li></ul><p><strong>打个比方</strong>：Redo Log是“账本的备份”，Undo Log是“橡皮擦”。服务器断电后，靠Redo Log重放恢复；写错了要撤销，靠Undo Log擦除重来。两者缺一不可。</p><hr><h3 id="_7-mysql中redo-log的两阶段提交-2pc-是什么-阿里p6-必问" tabindex="-1">7. MySQL中Redo Log的两阶段提交（2PC）是什么？（阿里P6+必问） <a class="header-anchor" href="#_7-mysql中redo-log的两阶段提交-2pc-是什么-阿里p6-必问" aria-label="Permalink to &quot;7. MySQL中Redo Log的两阶段提交（2PC）是什么？（阿里P6+必问）&quot;">​</a></h3><p><strong>背景</strong>：Redo Log是InnoDB引擎层的，Binlog是Server层的。事务提交时，需要保证两者<strong>逻辑一致</strong>，否则主从复制会出现数据不一致。</p><p><strong>两阶段提交流程</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">1. Prepare阶段：事务执行完毕，Redo Log写入磁盘（状态为prepare）</span></span>
<span class="line"><span class="__shiki_wvjl67">2. Commit阶段：Binlog写入磁盘 → Redo Log状态改为commit → 事务真正提交</span></span></code></pre></div><p><strong>崩溃恢复规则</strong>：</p><ul><li>Redo Log状态为 <strong>prepare</strong> + Binlog<strong>已完整写入</strong> → 事务<strong>提交</strong>（补全commit）</li><li>Redo Log状态为 <strong>prepare</strong> + Binlog<strong>未完整写入</strong> → 事务<strong>回滚</strong></li></ul><blockquote><p><strong>核心目的</strong>：保证Redo Log和Binlog的<strong>数据一致性</strong>，确保主从复制不出现数据偏差。</p></blockquote><hr><h3 id="_8-mysql的四种事务隔离级别及解决的问题-⭐必考" tabindex="-1">8. MySQL的四种事务隔离级别及解决的问题？（⭐必考） <a class="header-anchor" href="#_8-mysql的四种事务隔离级别及解决的问题-⭐必考" aria-label="Permalink to &quot;8. MySQL的四种事务隔离级别及解决的问题？（⭐必考）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>隔离级别</th><th>脏读</th><th>不可重复读</th><th>幻读</th></tr></thead><tbody><tr><td>READ UNCOMMITTED</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>READ COMMITTED (RC)</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td><strong>REPEATABLE READ (RR)</strong></td><td>❌</td><td>❌</td><td>⚠️（InnoDB通过MVCC+间隙锁解决）</td></tr><tr><td>SERIALIZABLE</td><td>❌</td><td>❌</td><td>❌</td></tr></tbody></table><blockquote><p>MySQL<strong>默认隔离级别是REPEATABLE READ（RR）</strong> 。</p></blockquote><hr><h3 id="_9-mvcc-多版本并发控制-的实现原理是什么-⭐必考-阿里必问" tabindex="-1">9. MVCC（多版本并发控制）的实现原理是什么？（⭐必考，阿里必问） <a class="header-anchor" href="#_9-mvcc-多版本并发控制-的实现原理是什么-⭐必考-阿里必问" aria-label="Permalink to &quot;9. MVCC（多版本并发控制）的实现原理是什么？（⭐必考，阿里必问）&quot;">​</a></h3><p>MVCC是InnoDB实现 <strong>&quot;读不加锁、写不阻塞读&quot;</strong> 的核心机制。基于 <strong>3个关键组件</strong>：</p><p><strong>① 隐藏列</strong>（每行数据包含）：</p><ul><li><code>DB_TRX_ID</code>：最后修改该行的事务ID（全局递增）</li><li><code>DB_ROLL_PTR</code>：回滚指针，指向undo log中的旧版本</li><li><code>DB_ROW_ID</code>：行ID（无主键时生成）</li></ul><p><strong>② Undo Log版本链</strong>：记录数据的历史版本，形成单向链表</p><p><strong>③ Read View</strong>（可见性视图）包含4个核心字段：</p><ul><li><code>m_ids</code>：当前活跃的事务ID集合</li><li><code>min_trx_id</code>：最小活跃事务ID</li><li><code>max_trx_id</code>：下一个分配的事务ID</li><li><code>creator_trx_id</code>：创建Read View的事务ID</li></ul><p><strong>可见性规则</strong>：</p><ul><li><code>DB_TRX_ID &lt; min_trx_id</code>：版本已提交，<strong>可见</strong></li><li><code>DB_TRX_ID &gt; max_trx_id</code>：版本未创建，<strong>不可见</strong></li><li><code>min_trx_id ≤ DB_TRX_ID ≤ max_trx_id</code>：若不在m_ids中则可见</li></ul><p><strong>RC vs RR的关键区别</strong>：</p><ul><li><strong>RR级别</strong>：事务内<strong>仅创建1次</strong>Read View（保证可重复读一致）</li><li><strong>RC级别</strong>：<strong>每次查询</strong>创建新Read View（能看到其他事务提交的修改）</li></ul><hr><h3 id="_10-面试完整话术-acid完整版" tabindex="-1">10. 面试完整话术（ACID完整版） <a class="header-anchor" href="#_10-面试完整话术-acid完整版" aria-label="Permalink to &quot;10. 面试完整话术（ACID完整版）&quot;">​</a></h3><p>“ACID中，一致性是最终目标，AID是三个技术支柱。</p><p>原子性靠Undo Log实现——记录修改前的旧值，回滚时逆向操作。持久性靠Redo Log实现——利用WAL技术，顺序写日志比随机写数据快得多，崩溃时重放恢复。</p><p>隔离性由MVCC和锁分工协作：MVCC处理读写并发（读快照不加锁），锁处理写写并发（行锁互斥）。</p><p>特别需要注意的是，Redo Log和Binlog通过两阶段提交保证一致性——Prepare阶段写Redo Log，Commit阶段写Binlog——这是崩溃恢复和主从复制一致性的基石。”</p><hr><h2 id="五、锁机制篇" tabindex="-1">五、锁机制篇 <a class="header-anchor" href="#五、锁机制篇" aria-label="Permalink to &quot;五、锁机制篇&quot;">​</a></h2><h3 id="_1-mysql中有哪几种锁-⭐必考" tabindex="-1">1. MySQL中有哪几种锁？（⭐必考） <a class="header-anchor" href="#_1-mysql中有哪几种锁-⭐必考" aria-label="Permalink to &quot;1. MySQL中有哪几种锁？（⭐必考）&quot;">​</a></h3><p>按锁粒度分类：</p><table tabindex="0"><thead><tr><th>锁类型</th><th>开销</th><th>加锁速度</th><th>死锁</th><th>并发度</th><th>适用引擎</th></tr></thead><tbody><tr><td><strong>表级锁</strong></td><td>小</td><td>快</td><td>不会出现</td><td>最低</td><td>MyISAM、InnoDB</td></tr><tr><td><strong>行级锁</strong></td><td>大</td><td>慢</td><td>可能出现</td><td>最高</td><td>InnoDB</td></tr></tbody></table><p>按锁类型分类：</p><table tabindex="0"><thead><tr><th>锁类型</th><th>关键词</th><th>兼容性</th><th>说明</th></tr></thead><tbody><tr><td><strong>共享锁（S锁/读锁）</strong></td><td><code>LOCK IN SHARE MODE</code></td><td>S锁之间兼容，与X锁互斥</td><td>允许其他事务读取，阻止写入</td></tr><tr><td><strong>排他锁（X锁/写锁）</strong></td><td><code>FOR UPDATE</code></td><td>与S/X锁均互斥</td><td>阻止其他事务读写</td></tr></tbody></table><p>InnoDB行锁的三种实现：</p><ul><li><strong>Record Lock（记录锁）</strong> ：锁住一行记录（永远加在索引上）</li><li><strong>Gap Lock（间隙锁）</strong> ：锁住索引记录之间的间隙（<strong>防止幻读</strong>）</li><li><strong>Next-Key Lock</strong>：Record Lock + Gap Lock的组合（RR默认）</li></ul><hr><h3 id="_2-意向锁-intention-lock-是什么-为什么需要它-⭐必考-大多数人的知识盲区" tabindex="-1">2. 意向锁（Intention Lock）是什么？为什么需要它？（⭐必考，大多数人的知识盲区） <a class="header-anchor" href="#_2-意向锁-intention-lock-是什么-为什么需要它-⭐必考-大多数人的知识盲区" aria-label="Permalink to &quot;2. 意向锁（Intention Lock）是什么？为什么需要它？（⭐必考，大多数人的知识盲区）&quot;">​</a></h3><blockquote><p>定义：意向锁是<strong>表级锁</strong>，由InnoDB自动添加，用于协调<strong>行锁与表锁</strong>之间的冲突检测。</p></blockquote><p>两种意向锁：</p><table tabindex="0"><thead><tr><th>意向锁类型</th><th>触发时机</th><th>兼容性</th></tr></thead><tbody><tr><td><strong>IS（意向共享锁）</strong></td><td>事务准备加S锁时，先加IS锁</td><td>IS之间兼容</td></tr><tr><td><strong>IX（意向排他锁）</strong></td><td>事务准备加X锁时，先加IX锁</td><td>IX之间兼容，但与S/X互斥</td></tr></tbody></table><p>为什么需要意向锁？（面试核心）</p><p>场景：事务A对某行加了行锁（X锁），此时事务B要加<strong>表锁</strong>（如 <code>LOCK TABLES t WRITE</code>）。</p><p><strong>没有意向锁</strong>：B必须遍历表中每一行，检查是否有行锁 → <strong>O(n)全表扫描</strong>，效率极低。 <strong>有意向锁</strong>：A加行锁前先加IX表级意向锁，B加表锁时只需检查表上是否有IX锁 → <strong>O(1)直接判断</strong>。</p><blockquote><p><strong>面试必杀句</strong>：“意向锁是<strong>表级锁的‘状态标识’</strong>，让表锁和行锁能在不同粒度上高效共存，避免全表遍历检测冲突。”</p></blockquote><hr><h3 id="_3-innodb行锁的三种实现中-锁永远加在索引上-是什么意思-关键底层认知" tabindex="-1">3. InnoDB行锁的三种实现中，“锁永远加在索引上”是什么意思？（关键底层认知） <a class="header-anchor" href="#_3-innodb行锁的三种实现中-锁永远加在索引上-是什么意思-关键底层认知" aria-label="Permalink to &quot;3. InnoDB行锁的三种实现中，“锁永远加在索引上”是什么意思？（关键底层认知）&quot;">​</a></h3><blockquote><p>核心规则：InnoDB的行锁<strong>不是锁在数据行本身</strong>，而是<strong>锁在索引记录（Index Record）上</strong>。</p></blockquote><p><strong>三种情况</strong>：</p><table tabindex="0"><thead><tr><th>场景</th><th>实际加锁对象</th><th>后果</th></tr></thead><tbody><tr><td><code>WHERE id = 1</code>（id是主键）</td><td>主键索引上的<strong>Record Lock</strong></td><td>精准锁一行</td></tr><tr><td><code>WHERE name = &#39;张三&#39;</code>（name有普通索引）</td><td>先锁二级索引记录，再锁聚簇索引记录</td><td>锁两棵树</td></tr><tr><td><code>WHERE age = 20</code>（age无索引）</td><td><strong>全表所有行的Record Lock</strong></td><td>行锁→<strong>表锁</strong>（性能灾难）</td></tr></tbody></table><blockquote><p><strong>面试必杀句</strong>：“行锁是<strong>索引锁</strong>，不是数据行锁。如果查询不走索引，InnoDB会锁定所有记录，行锁名存实亡，退化为表锁。这就是为什么<strong>索引设计不好会导致锁竞争爆炸</strong>。”</p></blockquote><hr><h3 id="_4-next-key-lock是如何防止幻读的-rr隔离级别的核心保障" tabindex="-1">4. Next-Key Lock是如何防止幻读的？（RR隔离级别的核心保障） <a class="header-anchor" href="#_4-next-key-lock是如何防止幻读的-rr隔离级别的核心保障" aria-label="Permalink to &quot;4. Next-Key Lock是如何防止幻读的？（RR隔离级别的核心保障）&quot;">​</a></h3><p>幻读场景：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 事务A（RR级别）</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> *</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_140thh"> user </span><span class="__shiki_1itgoe">WHERE</span><span class="__shiki_140thh"> age </span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_dzsirb"> 18</span><span class="__shiki_140thh">;  </span><span class="__shiki_21nrsd">-- 返回 1 条（id=1）</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 事务B</span></span>
<span class="line"><span class="__shiki_1itgoe">INSERT INTO</span><span class="__shiki_140thh"> user (id, age) </span><span class="__shiki_1itgoe">VALUES</span><span class="__shiki_140thh"> (</span><span class="__shiki_dzsirb">2</span><span class="__shiki_140thh">, </span><span class="__shiki_dzsirb">20</span><span class="__shiki_140thh">);  </span><span class="__shiki_21nrsd">-- 插入成功</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 事务A 再次执行</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> *</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_140thh"> user </span><span class="__shiki_1itgoe">WHERE</span><span class="__shiki_140thh"> age </span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_dzsirb"> 18</span><span class="__shiki_140thh">;  </span><span class="__shiki_21nrsd">-- 返回 2 条 → 幻读！</span></span></code></pre></div><p>Next-Key Lock的防御机制：</p><blockquote><p>事务A执行范围查询时，InnoDB不仅锁住已有的记录行（Record Lock），还<strong>锁住这些记录之间的间隙（Gap Lock）</strong>，阻止其他事务在间隙中插入新数据。</p></blockquote><table tabindex="0"><thead><tr><th>锁类型</th><th>锁住范围</th><th>目的</th></tr></thead><tbody><tr><td><strong>Record Lock</strong></td><td>已有的数据行</td><td>防止修改/删除</td></tr><tr><td><strong>Gap Lock</strong></td><td>数据行之间的间隙（含边界）</td><td>防止插入新行</td></tr></tbody></table><blockquote><p><strong>关键认知</strong>：间隙锁<strong>只存在于RR隔离级别</strong>，RC级别没有间隙锁——这也是RC无法防止幻读的根本原因。</p></blockquote><hr><h3 id="_5-rr隔离级别下-什么情况不会加-gap-lock-面试官的隐藏考点" tabindex="-1">5. RR隔离级别下，什么情况不会加 Gap Lock？（面试官的隐藏考点） <a class="header-anchor" href="#_5-rr隔离级别下-什么情况不会加-gap-lock-面试官的隐藏考点" aria-label="Permalink to &quot;5. RR隔离级别下，什么情况不会加 Gap Lock？（面试官的隐藏考点）&quot;">​</a></h3><p><strong>唯一索引的等值查询</strong>（且记录存在）时，只加 Record Lock，<strong>不加 Gap Lock</strong>。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- id 是唯一索引</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> *</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_140thh"> user </span><span class="__shiki_1itgoe">WHERE</span><span class="__shiki_140thh"> id </span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb"> 5</span><span class="__shiki_1itgoe"> FOR</span><span class="__shiki_1itgoe"> UPDATE</span><span class="__shiki_140thh">;  </span><span class="__shiki_21nrsd">-- id=5存在 → 仅Record Lock，无间隙锁</span></span></code></pre></div><blockquote><p><strong>原因</strong>：唯一索引等值查询不会产生幻读（结果集确定且唯一），无需间隙锁保护。</p></blockquote><hr><h3 id="_6-死锁的四个必要条件-如何排查和避免-⭐必考" tabindex="-1">6. 死锁的四个必要条件？如何排查和避免？（⭐必考） <a class="header-anchor" href="#_6-死锁的四个必要条件-如何排查和避免-⭐必考" aria-label="Permalink to &quot;6. 死锁的四个必要条件？如何排查和避免？（⭐必考）&quot;">​</a></h3><p>死锁产生的四个必要条件（缺一不可）：</p><table tabindex="0"><thead><tr><th>条件</th><th>说明</th></tr></thead><tbody><tr><td>① <strong>互斥</strong></td><td>资源同一时刻只能被一个事务占有</td></tr><tr><td>② <strong>持有并等待</strong></td><td>持有锁的事务在等待其他锁，不释放已持有的锁</td></tr><tr><td>③ <strong>不可抢占</strong></td><td>已获取的锁不能被强制剥夺</td></tr><tr><td>④ <strong>循环等待</strong></td><td>事务之间形成锁等待环路</td></tr></tbody></table><p>排查方法：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 1. 查看当前锁信息（MySQL 8.0）</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> *</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_dzsirb"> performance_schema</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">data_locks</span><span class="__shiki_140thh">;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 2. 查看最近一次死锁日志（关键！）</span></span>
<span class="line"><span class="__shiki_140thh">SHOW ENGINE INNODB </span><span class="__shiki_1itgoe">STATUS</span><span class="__shiki_140thh">;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 3. 开启死锁检测（默认开启）</span></span>
<span class="line"><span class="__shiki_140thh">SHOW VARIABLES </span><span class="__shiki_1itgoe">LIKE</span><span class="__shiki_mdbnqw"> &#39;innodb_deadlock_detect&#39;</span><span class="__shiki_140thh">;</span></span></code></pre></div><p>死锁日志关键信息：</p><ul><li><code>LATEST DETECTED DEADLOCK</code>：死锁详情</li><li><code>WAITING FOR THIS LOCK TO BE GRANTED</code>：当前等待的锁</li><li><code>HOLDS THE LOCK</code>：当前持有的锁</li></ul><p>六大避免策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>具体做法</th></tr></thead><tbody><tr><td><strong>①统一访问顺序</strong></td><td>所有事务按相同顺序访问表和行（如先主键升序）</td></tr><tr><td><strong>②缩短事务</strong></td><td>减少锁持有时间，及时提交</td></tr><tr><td><strong>③降低隔离级别</strong></td><td>改用RC级别（消除间隙锁，降低死锁概率）</td></tr><tr><td><strong>④合理设计索引</strong></td><td>精准索引减小锁范围，避免锁升级</td></tr><tr><td><strong>⑤使用 <code>NOWAIT</code> / <code>SKIP LOCKED</code>（8.0）</strong></td><td>遇到锁冲突立即返回而非等待</td></tr><tr><td><strong>⑥控制并发度</strong></td><td>限流或排队机制，减少锁竞争</td></tr></tbody></table><hr><h3 id="_7-乐观锁和悲观锁是什么-与mysql锁机制的关系" tabindex="-1">7. 乐观锁和悲观锁是什么？与MySQL锁机制的关系？ <a class="header-anchor" href="#_7-乐观锁和悲观锁是什么-与mysql锁机制的关系" aria-label="Permalink to &quot;7. 乐观锁和悲观锁是什么？与MySQL锁机制的关系？&quot;">​</a></h3><blockquote><p>虽然乐观锁<strong>不是MySQL内置机制</strong>，但面试中经常被混淆，建议明确区分：</p></blockquote><table tabindex="0"><thead><tr><th>维度</th><th>悲观锁</th><th>乐观锁</th></tr></thead><tbody><tr><td><strong>核心思想</strong></td><td>假设冲突必然发生，提前加锁</td><td>假设冲突不会发生，提交时检查</td></tr><tr><td><strong>实现方式</strong></td><td>MySQL 行锁/表锁</td><td>应用层版本号（<code>version</code>字段）或CAS</td></tr><tr><td><strong>适用场景</strong></td><td>写多读少、高冲突（如扣库存）</td><td>读多写少、低冲突</td></tr><tr><td><strong>性能特点</strong></td><td>加锁开销大，但数据一致性强</td><td>无锁开销，但冲突时重试成本高</td></tr></tbody></table><blockquote><p><strong>面试必杀句</strong>：“悲观锁依赖MySQL内核的<strong>行锁/间隙锁</strong>保证并发安全；乐观锁是应用层通过<strong>版本号+业务重试</strong>实现的，两者并不互斥，可配合使用（如先乐观后悲观兜底）。”</p></blockquote><hr><h3 id="_8-面试完整话术-锁机制完整版" tabindex="-1">8. 面试完整话术（锁机制完整版） <a class="header-anchor" href="#_8-面试完整话术-锁机制完整版" aria-label="Permalink to &quot;8. 面试完整话术（锁机制完整版）&quot;">​</a></h3><ul><li>“InnoDB的锁体系分三层：<strong>锁类型</strong>（共享/排他）、<strong>锁粒度</strong>（表级/行级）、<strong>锁算法</strong>（Record/Gap/Next-Key）。</li><li>行锁实际是<strong>索引锁</strong>，不走索引会导致锁全表——这是线上性能爆炸的头号杀手。</li><li>意向锁是<strong>表级的状态标识</strong>，让表锁和行锁能高效共存，避免全表遍历检测冲突。</li><li>RR级别下，范围查询会触发 <strong>Next-Key Lock = Record Lock + Gap Lock</strong>，这是防止幻读的核心机制。但唯一索引等值查询存在时，只加Record Lock。</li><li>死锁的四个必要条件（互斥、持有等待、不可抢占、循环等待）缺一不可。实践中通过<strong>统一访问顺序、缩短事务、RC隔离级别</strong>来规避。</li><li>乐观锁不是MySQL机制，而是应用层版本号方案——两者可以结合使用。”</li></ul><hr><h2 id="六、日志篇" tabindex="-1">六、日志篇 <a class="header-anchor" href="#六、日志篇" aria-label="Permalink to &quot;六、日志篇&quot;">​</a></h2><h3 id="_1-mysql的三大核心日志是什么-⭐必考" tabindex="-1">1. MySQL的三大核心日志是什么？（⭐必考） <a class="header-anchor" href="#_1-mysql的三大核心日志是什么-⭐必考" aria-label="Permalink to &quot;1. MySQL的三大核心日志是什么？（⭐必考）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日志</th><th>实现层</th><th>记录内容</th><th>核心作用</th></tr></thead><tbody><tr><td><strong>Redo Log</strong></td><td>InnoDB</td><td>数据页的物理变化（新值）</td><td><strong>崩溃恢复</strong>（持久性）</td></tr><tr><td><strong>Undo Log</strong></td><td>InnoDB</td><td>数据修改前的状态（旧值）</td><td><strong>事务回滚</strong> + MVCC</td></tr><tr><td><strong>Binlog</strong></td><td>Server层</td><td>逻辑SQL语句/行数据变化</td><td><strong>主从复制</strong> + 数据恢复</td></tr></tbody></table><h3 id="_2-redo-log的写入机制详解-wal-环形缓冲" tabindex="-1">2. Redo Log的写入机制详解（WAL + 环形缓冲） <a class="header-anchor" href="#_2-redo-log的写入机制详解-wal-环形缓冲" aria-label="Permalink to &quot;2. Redo Log的写入机制详解（WAL + 环形缓冲）&quot;">​</a></h3><blockquote><p><strong>WAL（Write-Ahead Logging）</strong>：事务提交时，<strong>先写Redo Log到磁盘</strong>，再写数据页到磁盘。保证崩溃时未刷盘的数据可通过Redo Log恢复。</p></blockquote><p>Redo Log的组成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">+-------------------+     +-------------------+</span></span>
<span class="line"><span class="__shiki_wvjl67">|  Redo Log Buffer  | --&gt; |  Redo Log File    |</span></span>
<span class="line"><span class="__shiki_wvjl67">|   （内存）         |     |   （磁盘，环形）   |</span></span>
<span class="line"><span class="__shiki_wvjl67">+-------------------+     +-------------------+</span></span>
<span class="line"><span class="__shiki_wvjl67">         ↓                        ↓</span></span>
<span class="line"><span class="__shiki_wvjl67">    innodb_flush_log_at_trx_commit 控制刷盘时机</span></span></code></pre></div><p>Redo Log Buffer → 磁盘的三种刷盘策略（面试高频参数）：</p><table tabindex="0"><thead><tr><th>参数值</th><th>含义</th><th>性能</th><th>安全性</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>每秒刷一次，事务提交时不刷</td><td>最高</td><td>崩溃可能丢1秒数据</td></tr><tr><td><strong>1</strong>（默认）</td><td>每次事务提交立即刷盘</td><td>最低</td><td><strong>最安全</strong>（不丢数据）</td></tr><tr><td><strong>2</strong></td><td>每次事务提交写入OS缓存，每秒刷盘</td><td>较高</td><td>操作系统崩溃可能丢1秒数据</td></tr></tbody></table><blockquote><p><strong>面试必杀句</strong>：“生产环境必须设置为 <strong>1</strong>。设为0或2虽然提升性能，但无法保证持久性，违背了Durability的基本要求。如果实在有性能瓶颈，优先优化SQL和索引，而不是降低刷盘策略。”</p></blockquote><hr><h3 id="_3-binlog的三种格式对比-⭐必考-阿里常问" tabindex="-1">3. Binlog的三种格式对比（⭐必考，阿里常问） <a class="header-anchor" href="#_3-binlog的三种格式对比-⭐必考-阿里常问" aria-label="Permalink to &quot;3. Binlog的三种格式对比（⭐必考，阿里常问）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>记录内容</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>STATEMENT</strong></td><td>执行的SQL语句</td><td>日志量小，性能高</td><td><code>NOW()</code>、<code>UUID()</code>等函数会导致主从数据不一致</td></tr><tr><td><strong>ROW</strong>（MySQL 5.7+ 推荐）</td><td>每行数据的变化（前/后镜像）</td><td>数据一致性最强（精确到行）</td><td>日志量大（批量操作记录每条变更）</td></tr><tr><td><strong>MIXED</strong></td><td>自动判断：安全时用STATEMENT，不安全时用ROW</td><td>兼顾性能和一致性</td><td>混合模式，行为不易预测</td></tr></tbody></table><blockquote><p><strong>面试必杀句</strong>：“生产环境强烈推荐使用 <strong>ROW格式</strong>。虽然日志量大，但保证了主从数据的绝对一致。尤其是阿里Canal等数据同步工具，必须依赖ROW格式解析Binlog。”</p></blockquote><hr><h3 id="_4-redo-log和binlog是如何保证数据一致的-两阶段提交-2pc" tabindex="-1">4. Redo Log和Binlog是如何保证数据一致的？（两阶段提交 2PC） <a class="header-anchor" href="#_4-redo-log和binlog是如何保证数据一致的-两阶段提交-2pc" aria-label="Permalink to &quot;4. Redo Log和Binlog是如何保证数据一致的？（两阶段提交 2PC）&quot;">​</a></h3><p>这是日志篇的<strong>核心灵魂</strong>，直接回答“崩溃恢复时如何保证数据不丢且主从不乱”。</p><p><strong>两阶段提交流程</strong>：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 事务执行 UPDATE user SET age = 20 WHERE id = 1;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_1itgoe">+</span><span class="__shiki_21nrsd">-----------------------------------------------------------+</span></span>
<span class="line"><span class="__shiki_140thh">| 阶段1：事务执行阶段                                         |</span></span>
<span class="line"><span class="__shiki_140thh">|   → 修改Buffer Pool中的数据页（脏页）                       |</span></span>
<span class="line"><span class="__shiki_140thh">|   → 写入Undo </span><span class="__shiki_1itgoe">Log</span><span class="__shiki_140thh">（用于回滚）                               |</span></span>
<span class="line"><span class="__shiki_1itgoe">+</span><span class="__shiki_21nrsd">-----------------------------------------------------------+</span></span>
<span class="line"><span class="__shiki_140thh">                              ↓</span></span>
<span class="line"><span class="__shiki_1itgoe">+</span><span class="__shiki_21nrsd">-----------------------------------------------------------+</span></span>
<span class="line"><span class="__shiki_140thh">| 阶段2：Prepare阶段                                          |</span></span>
<span class="line"><span class="__shiki_140thh">|   → Redo Log写入磁盘（状态标记为 prepare）                  |</span></span>
<span class="line"><span class="__shiki_1itgoe">+</span><span class="__shiki_21nrsd">-----------------------------------------------------------+</span></span>
<span class="line"><span class="__shiki_140thh">                              ↓</span></span>
<span class="line"><span class="__shiki_1itgoe">+</span><span class="__shiki_21nrsd">-----------------------------------------------------------+</span></span>
<span class="line"><span class="__shiki_140thh">| 阶段3：Commit阶段                                           |</span></span>
<span class="line"><span class="__shiki_140thh">|   → Binlog写入磁盘                                          |</span></span>
<span class="line"><span class="__shiki_140thh">|   → Redo Log状态改为 </span><span class="__shiki_1itgoe">commit</span><span class="__shiki_140thh">（事务真正提交）                 |</span></span>
<span class="line"><span class="__shiki_140thh">|   → 返回客户端“提交成功”                                    |</span></span>
<span class="line"><span class="__shiki_1itgoe">+</span><span class="__shiki_21nrsd">-----------------------------------------------------------+</span></span></code></pre></div><p><strong>崩溃恢复规则（关键！）</strong> ：</p><table tabindex="0"><thead><tr><th>崩溃时Redo Log状态</th><th>Binlog状态</th><th>MySQL恢复后的处理</th><th>原因</th></tr></thead><tbody><tr><td><strong>prepare</strong></td><td><strong>完整</strong></td><td><strong>提交事务</strong>（重放Redo Log）</td><td>Binlog已写入，主从需保持一致</td></tr><tr><td><strong>prepare</strong></td><td><strong>不完整/未写入</strong></td><td><strong>回滚事务</strong>（用Undo Log撤销）</td><td>Binlog没写，回滚保证数据一致</td></tr><tr><td><strong>commit</strong></td><td>完整</td><td><strong>提交事务</strong></td><td>已经提交，直接恢复</td></tr></tbody></table><blockquote><p><strong>面试必杀句</strong>：“两阶段提交保证了<strong>Redo Log和Binlog的逻辑一致性</strong>。崩溃恢复时，只要Binlog完整写入，哪怕Redo Log还是prepare状态，也要提交——因为Binlog已经发给从库了，主库不提交就会导致主从不一致。”</p></blockquote><hr><h3 id="_5-为什么binlog是追加写-redo-log是循环写-进一步深挖" tabindex="-1">5. 为什么Binlog是追加写，Redo Log是循环写？（进一步深挖） <a class="header-anchor" href="#_5-为什么binlog是追加写-redo-log是循环写-进一步深挖" aria-label="Permalink to &quot;5. 为什么Binlog是追加写，Redo Log是循环写？（进一步深挖）&quot;">​</a></h3><ul><li><strong>Redo Log</strong>：只需要保留<strong>未刷盘的修改记录</strong>，脏页刷盘后即可覆盖重用</li><li><strong>Binlog</strong>：需要保留<strong>完整历史记录</strong>用于主从复制和数据恢复，必须追加写</li></ul><blockquote><p><strong>WAL技术（Write-Ahead Logging）</strong> ：先写日志，再写磁盘——保证崩溃后可通过Redo Log恢复。</p></blockquote><p>Redo Log循环写：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">+----------+----------+----------+----------+----------+</span></span>
<span class="line"><span class="__shiki_wvjl67">|  文件1    |  文件2    |  文件3    |  文件4    |  文件1 ← |</span></span>
<span class="line"><span class="__shiki_wvjl67">+----------+----------+----------+----------+----------+</span></span>
<span class="line"><span class="__shiki_wvjl67">     ↑                    ↑</span></span>
<span class="line"><span class="__shiki_wvjl67">  write pos           checkpoint</span></span>
<span class="line"><span class="__shiki_wvjl67">  （当前写入位置）     （已刷盘位置）</span></span></code></pre></div><ul><li><strong>write pos</strong>：当前写入位置，顺序向后移动</li><li><strong>checkpoint</strong>：已刷盘的位置，该位置之前的日志对应的脏页已落盘，可以覆盖</li><li><strong>当 write pos 追上 checkpoint</strong>：所有Redo Log空间已用完，此时会<strong>强制刷盘</strong>（性能下降，说明Redo Log文件配置偏小）</li></ul><blockquote><p><strong>关键配置</strong>：<code>innodb_log_files_in_group</code>（默认2个文件）和<code>innodb_log_file_size</code>（默认48MB）需根据写入量调整。设置过小会导致频繁刷盘，设置过大则崩溃恢复变慢。</p></blockquote><p>Binlog追加写：</p><ul><li>主要用于<strong>主从复制</strong>和<strong>PITR（Point-In-Time Recovery，时间点恢复）</strong></li><li>需要保留完整历史，通过<code>expire_logs_days</code>或<code>binlog_expire_logs_seconds</code>设置保留周期</li><li>支持<strong>GTID（全局事务ID）</strong>，简化主从故障切换</li></ul><hr><h3 id="_6-undo-log的两种核心用途-不只是回滚" tabindex="-1">6. Undo Log的两种核心用途（不只是回滚） <a class="header-anchor" href="#_6-undo-log的两种核心用途-不只是回滚" aria-label="Permalink to &quot;6. Undo Log的两种核心用途（不只是回滚）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用途</th><th>说明</th></tr></thead><tbody><tr><td><strong>事务回滚</strong></td><td>执行<code>ROLLBACK</code>时，通过Undo Log逆向操作恢复旧数据</td></tr><tr><td><strong>MVCC一致性读</strong></td><td>事务需要读取某个历史版本的数据时，通过Undo Log版本链回溯到可见版本</td></tr></tbody></table><p>Undo Log版本链示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">+---------+     +---------+     +---------+</span></span>
<span class="line"><span class="__shiki_wvjl67">| 版本3    | ←-- | 版本2    | ←-- | 版本1    |</span></span>
<span class="line"><span class="__shiki_wvjl67">| (当前值) |     | (旧值)   |     | (初始值) |</span></span>
<span class="line"><span class="__shiki_wvjl67">+---------+     +---------+     +---------+</span></span>
<span class="line"><span class="__shiki_wvjl67">     ↑                ↑</span></span>
<span class="line"><span class="__shiki_wvjl67"> DB_TRX_ID=5      DB_TRX_ID=3</span></span></code></pre></div><blockquote><p><strong>RR与RC的区别</strong>：RR级别在整个事务中使用<strong>同一个Read View</strong>，通过Undo Log版本链保证可重复读；RC级别每次查询<strong>新建Read View</strong>，能看到其他事务已提交的最新版本。</p></blockquote><hr><h3 id="_7-三大日志的写入时机对比-面试官终极拷问" tabindex="-1">7. 三大日志的写入时机对比（面试官终极拷问） <a class="header-anchor" href="#_7-三大日志的写入时机对比-面试官终极拷问" aria-label="Permalink to &quot;7. 三大日志的写入时机对比（面试官终极拷问）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>Redo Log</th><th>Undo Log</th><th>Binlog</th></tr></thead><tbody><tr><td><code>START TRANSACTION</code></td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>执行<code>INSERT</code>/<code>UPDATE</code>/<code>DELETE</code></td><td>✅ 写入Buffer</td><td>✅ 写入Buffer</td><td>❌（提交时才写）</td></tr><tr><td><code>COMMIT</code></td><td>✅ <strong>Prepare</strong> + <strong>Commit</strong> 两阶段刷盘</td><td>❌</td><td>✅ <strong>Commit阶段刷盘</strong></td></tr><tr><td><code>ROLLBACK</code></td><td>❌（不需要）</td><td>✅ 用于恢复旧数据</td><td>❌（不会记录回滚）</td></tr></tbody></table><blockquote><p><strong>面试必杀句</strong>：“Undo Log在事务执行过程中实时写入，回滚时使用；Redo Log在事务提交时两阶段刷盘（Prepare + Commit）；Binlog只在Commit阶段写入。三者各有独立的写入时机和生命周期。”</p></blockquote><hr><h3 id="_8-mysql-8-0-vs-5-7-的日志相关变化" tabindex="-1">8. MySQL 8.0 vs 5.7 的日志相关变化 <a class="header-anchor" href="#_8-mysql-8-0-vs-5-7-的日志相关变化" aria-label="Permalink to &quot;8. MySQL 8.0 vs 5.7 的日志相关变化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变化点</th><th>MySQL 5.7</th><th>MySQL 8.0</th></tr></thead><tbody><tr><td>Binlog默认格式</td><td><code>MIXED</code></td><td><strong><code>ROW</code></strong></td></tr><tr><td>Binlog过期设置</td><td><code>expire_logs_days</code></td><td><code>binlog_expire_logs_seconds</code>（更精确）</td></tr><tr><td>Redo Log大小</td><td>最多4组文件，最大512GB</td><td>最多32组文件，最大512GB</td></tr><tr><td>Undo Log存储</td><td>系统表空间（<code>ibdata1</code>）</td><td>独立Undo表空间（可独立回收）</td></tr></tbody></table><hr><h3 id="_9-面试完整话术-日志篇完整版" tabindex="-1">9. 面试完整话术（日志篇完整版） <a class="header-anchor" href="#_9-面试完整话术-日志篇完整版" aria-label="Permalink to &quot;9. 面试完整话术（日志篇完整版）&quot;">​</a></h3><p>“MySQL的三大日志各有分工：</p><ul><li><p>Redo Log是InnoDB引擎层的<strong>物理日志</strong>，负责崩溃恢复。它采用<strong>环形缓冲</strong>和<strong>WAL技术</strong>，事务提交时先刷Redo Log再刷数据页，保证了持久性。生产环境必须设置 <code>innodb_flush_log_at_trx_commit = 1</code>，确保每次提交都刷盘。</p></li><li><p>Undo Log是<strong>逻辑日志</strong>，记录修改前的旧值，用于事务回滚和MVCC一致性读。它通过版本链实现可重复读，RR级别整个事务使用同一个Read View，RC级别每次查询新建。</p></li><li><p>Binlog是Server层的<strong>逻辑日志</strong>，负责主从复制和数据恢复。推荐使用<strong>ROW格式</strong>保证主从一致性。事务提交时，Redo Log和Binlog通过<strong>两阶段提交</strong>保证一致性——Redo Log先prepare，再写Binlog，最后Redo Log commit。崩溃恢复时，只要Binlog完整就提交，否则回滚，确保主从不偏离。</p></li></ul><p>三者中，Redo Log和Binlog的<strong>2PC协议</strong>是分布式事务一致性保障的经典范式，在TCC、Seata等分布式事务方案中也能看到类似的影子。”</p><hr><h2 id="七、sql优化篇" tabindex="-1">七、SQL优化篇 <a class="header-anchor" href="#七、sql优化篇" aria-label="Permalink to &quot;七、SQL优化篇&quot;">​</a></h2><h3 id="_18-工作中优化mysql的手段有哪些-⭐必考" tabindex="-1">18. 工作中优化MySQL的手段有哪些？（⭐必考） <a class="header-anchor" href="#_18-工作中优化mysql的手段有哪些-⭐必考" aria-label="Permalink to &quot;18. 工作中优化MySQL的手段有哪些？（⭐必考）&quot;">​</a></h3><ol><li><strong>索引优化</strong>：确保高频查询字段有合适索引</li><li><strong>SQL优化</strong>：减少全表扫描、避免不必要计算</li><li><strong>事务与锁优化</strong>：避免长事务、使用批量插入</li><li><strong>架构优化</strong>：读写分离或分库分表</li></ol><h3 id="_19-如何定位慢查询" tabindex="-1">19. 如何定位慢查询？ <a class="header-anchor" href="#_19-如何定位慢查询" aria-label="Permalink to &quot;19. 如何定位慢查询？&quot;">​</a></h3><ol><li>开启<strong>慢查询日志</strong>，捕获执行时间超过阈值的SQL</li><li>使用<strong>EXPLAIN</strong>分析执行计划</li><li>关注EXPLAIN关键字段： <ul><li><strong>type</strong>：访问类型（<code>ALL</code>/<code>index</code>需警惕）</li><li><strong>rows</strong>：扫描行数</li><li><strong>Extra</strong>：关注<code>Using index</code>（覆盖索引）、<code>Using filesort</code>（文件排序）</li></ul></li></ol><h3 id="_20-唯一索引比普通索引快吗-为什么" tabindex="-1">20. 唯一索引比普通索引快吗？为什么？ <a class="header-anchor" href="#_20-唯一索引比普通索引快吗-为什么" aria-label="Permalink to &quot;20. 唯一索引比普通索引快吗？为什么？&quot;">​</a></h3><p><strong>不一定快，反而可能慢</strong>。</p><ul><li><strong>查询时</strong>：唯一索引查到一条就停止；普通索引查到多条，但差距<strong>极小</strong>（内存操作）</li><li><strong>插入时</strong>：唯一索引需检查唯一性约束，<strong>比普通索引慢</strong></li><li><strong>建议</strong>：业务上需要唯一性才用唯一索引，否则用普通索引</li></ul><h2 id="八、分库分表与高可用篇" tabindex="-1">八、分库分表与高可用篇 <a class="header-anchor" href="#八、分库分表与高可用篇" aria-label="Permalink to &quot;八、分库分表与高可用篇&quot;">​</a></h2><h3 id="_21-什么时候需要考虑分库分表-⭐进阶必问" tabindex="-1">21. 什么时候需要考虑分库分表？（⭐进阶必问） <a class="header-anchor" href="#_21-什么时候需要考虑分库分表-⭐进阶必问" aria-label="Permalink to &quot;21. 什么时候需要考虑分库分表？（⭐进阶必问）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>阈值</th></tr></thead><tbody><tr><td>单表数据量</td><td>超过<strong>5000万</strong>行且持续增长</td></tr><tr><td>单库并发（写QPS）</td><td>&gt;1000</td></tr><tr><td>单库磁盘使用率</td><td>&gt;80%且无法清理</td></tr></tbody></table><blockquote><p>阿里巴巴《Java开发手册》规定：单表超过<strong>500万</strong>或大小超<strong>2GB</strong>时考虑分库分表。</p></blockquote><h3 id="_22-垂直拆分和水平拆分的区别是什么-⭐必考" tabindex="-1">22. 垂直拆分和水平拆分的区别是什么？（⭐必考） <a class="header-anchor" href="#_22-垂直拆分和水平拆分的区别是什么-⭐必考" aria-label="Permalink to &quot;22. 垂直拆分和水平拆分的区别是什么？（⭐必考）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>垂直拆分</th><th>水平拆分</th></tr></thead><tbody><tr><td>拆分依据</td><td>业务模块/字段访问频率</td><td>数据行的某种规则</td></tr><tr><td>表结构</td><td>不同表结构不同</td><td><strong>所有表结构完全相同</strong></td></tr><tr><td>解决问题</td><td>业务耦合、单库连接压力</td><td>单表数据量过大</td></tr><tr><td>跨库JOIN</td><td>较多</td><td>较少</td></tr><tr><td>扩容难度</td><td>低（按业务新增库）</td><td>高（需数据迁移）</td></tr></tbody></table><h3 id="_23-mysql主从同步的三种机制-⭐必考" tabindex="-1">23. MySQL主从同步的三种机制？（⭐必考） <a class="header-anchor" href="#_23-mysql主从同步的三种机制-⭐必考" aria-label="Permalink to &quot;23. MySQL主从同步的三种机制？（⭐必考）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>机制</th><th>原理</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>异步复制</strong>（默认）</td><td>主库执行完立即返回，不等待从库</td><td>性能高，延迟低</td><td>主库宕机可能丢数据</td></tr><tr><td><strong>半同步复制</strong></td><td>主库等待至少一个从库写入relay log后返回</td><td>数据一致性较好</td><td>性能下降</td></tr><tr><td><strong>组复制（5.7+）</strong></td><td>基于Paxos的多主复制</td><td>自动故障转移，强一致性</td><td>配置复杂</td></tr></tbody></table><h3 id="_24-主从延迟的原因及解决方案" tabindex="-1">24. 主从延迟的原因及解决方案？ <a class="header-anchor" href="#_24-主从延迟的原因及解决方案" aria-label="Permalink to &quot;24. 主从延迟的原因及解决方案？&quot;">​</a></h3><p><strong>产生原因</strong>：</p><ul><li>主库高并发写、从库单线程重放</li><li>大事务执行、网络延迟</li></ul><p><strong>解决方案</strong>：</p><ol><li>拆分大事务为小事务</li><li>使用半同步复制</li><li>实时性要求高的读操作<strong>走主库</strong></li><li>引入Redis缓存层</li><li>升级从库硬件</li></ol><p>以上是MySQL面试的核心高频考点，覆盖了<strong>架构、存储引擎、索引、事务、锁、日志、SQL优化、分库分表、主从复制</strong>等全部核心模块。建议重点掌握<strong>索引</strong>（尤其是B+树原理、回表、索引失效场景）和<strong>事务</strong>（MVCC、隔离级别）两大板块，这两部分占据了面试中的绝大部分问题。</p>`,289)])])}const _=s(r,[["render",d]]);export{c as __pageData,_ as default};
